function threadRight(root: TreeNode | null): void {
  const order: TreeNode[] = [];
  const stack: TreeNode[] = root ? [root] : [];
  while (stack.length) {
    const n = stack.pop()!;
    order.push(n);
    if (n.right) stack.push(n.right);
    if (n.left) stack.push(n.left); // left is popped first
  }
  for (let i = 0; i < order.length; i++) {
    order[i].left = null;
    order[i].right = i + 1 < order.length ? order[i + 1] : null;
  }
}

