class Solution:
    def threadRight(self, root: Optional[TreeNode]) -> None:
        order = []
        stack = [root] if root else []
        while stack:
            n = stack.pop()
            order.append(n)
            if n.right:
                stack.append(n.right)
            if n.left:
                stack.append(n.left)  # left is popped first
        for i, n in enumerate(order):
            n.left = None
            n.right = order[i + 1] if i + 1 < len(order) else None

